// Validate: products must already be verified (have source_url). No products -> UNAVAILABLE, not fake offers.
const i = $input.first().json;
if (!i.procurement_id) throw new Error('Missing procurement_id');
const products = Array.isArray(i.products) ? i.products : [];
for (const p of products) if (!p.source_url) throw new Error('Unverified product passed to vendor research: ' + (p.product_id ?? '?'));
return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, currency: i.currency ?? 'USD', products } }];

// Enforce vendor output rules: URL required, price>0 with currency, no cross-currency compare here.
const out = $input.first().json?.output ?? $input.first().json;
const inp = $('Validate Input').first().json;
const offers = Array.isArray(out.offers) ? out.offers : [];
const pids = new Set(inp.products.map((p) => p.product_id));
for (const o of offers) {
  if (!pids.has(o.product_id)) throw new Error('Offer references unknown product: ' + o.offer_id);
  if (!o.source_url) throw new Error('Rejecting offer without source_url: ' + o.offer_id);
  if (typeof o.unit_price === 'number') { if (!(o.unit_price > 0)) throw new Error('Invalid price: ' + o.offer_id); if (!o.currency) throw new Error('Price without currency: ' + o.offer_id); }
  for (const f of ['delivery_days','warranty_months','payment_terms','availability']) if (o[f] === null || o[f] === '') throw new Error(`Field ${f} must be value or "unavailable": ` + o.offer_id);
}
const live = offers.filter((o) => o.data_status === 'LIVE').length;
const seenV = new Set();
const vendors = [];
for (const o of offers) {
  if (seenV.has(o.vendor_id)) continue;
  seenV.add(o.vendor_id);
  if (!o.vendor_name || o.vendor_name === 'unavailable') throw new Error('Offer without verified merchant: ' + o.offer_id);
  vendors.push({ vendor_id: o.vendor_id, vendor_name: o.vendor_name, vendor_url: o.source_url, source: o.source, source_url: o.source_url, retrieved_at: o.retrieved_at, data_status: o.data_status, confidence: o.confidence ?? 0.6, raw: { derived_from_offer: o.offer_id } });
}
return [{ json: { procurement_id: inp.procurement_id, offers, vendors, data_status: offers.length === 0 ? 'UNAVAILABLE' : live === offers.length ? 'LIVE' : 'PARTIAL', unavailable_reasons: offers.length === 0 ? ['No verifiable vendor offers from configured providers'] : [] } }];

// Deterministic vendor query (no LLM): top product names as one search.
// Attribution to products happens in Normalize Offers via serpapi_product_id join.
const inp = $('Validate Input').first().json;
const names = (inp.products ?? []).slice(0, 5).map((p) => p.name).filter(Boolean).join(' ').slice(0, 300);
return [{ json: { tool: 'vendor-search', query: names || 'business laptop', max_results: 10 } }];

// Deterministic offer normalization (no LLM): SerpAPI commercial evidence only.
// Tavily enrichment results NEVER become offers. Attribution via serpapi_product_id
// join against input products; unmatched listings are skipped, never cross-attached.
// Prices parsed from explicit symbols/codes only; 'starting from' and bare numbers
// without currency are rejected as offers.
const parsePrice = (raw) => {
  if (typeof raw === 'number') return raw > 0 ? { price: raw, currency: null } : {};
  if (typeof raw !== 'string') return {};
  const s = raw.trim();
  if (/starting from/i.test(s)) return {};
  let currency = null;
  if (s.includes('\u20B9')) currency = 'INR';
  else if (s.includes('\u20AC')) currency = 'EUR';
  else if (s.includes('\u00A3')) currency = 'GBP';
  else if (s.includes('$')) currency = 'USD';
  const cm = s.match(/\b(INR|USD|EUR|GBP|JPY|CAD|AUD)\b/i);
  if (cm) currency = cm[1].toUpperCase();
  const m = s.replace(/,/g, '').match(/(\d+(?:\.\d+)?)/);
  const price = m ? Number(m[1]) : null;
  if (!(price > 0)) return {};
  return { price, currency };
};
const items = $input.all().map((i) => i.json);
const inp = $('Validate Input').first().json;
const procShort = String(inp.procurement_id || '').replace(/-/g, '').slice(0, 8);
const byPid = {};
for (const p of (inp.products ?? [])) {
  const sid = p.raw && p.raw.serpapi_product_id;
  if (sid && sid !== 'unavailable') byPid[sid] = p;
}
const seen = new Set();
const offers = [];
const skipped = { noncommercial: 0, unmatched: 0, incomplete: 0 };
for (const e of items) {
  if (!e || e.data_status === 'UNAVAILABLE' || e.source !== 'serpapi_shopping') { skipped.noncommercial++; continue; }
  const d = e.data || {};
  const prod = d.serpapi_product_id ? byPid[d.serpapi_product_id] : null;
  if (!prod) { skipped.unmatched++; continue; }
  const pr = parsePrice(d.price);
  if (!(pr.price > 0) || !pr.currency) { skipped.incomplete++; continue; }
  const merchant = (typeof d.merchant_name === 'string' && d.merchant_name !== 'unavailable') ? d.merchant_name : null;
  if (!merchant || !e.source_url) { skipped.incomplete++; continue; }
  const key = prod.product_id + '|' + merchant.toLowerCase() + '|' + e.source_url;
  if (seen.has(key)) continue;
  seen.add(key);
  const mslug = merchant.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 30) || 'vendor';
  offers.push({
    offer_id: 'o-' + procShort + '-' + mslug + '-' + seen.size,
    product_id: prod.product_id,
    vendor_id: 'v-' + mslug + '-' + procShort + '-' + seen.size,
    vendor_name: merchant,
    unit_price: pr.price,
    currency: pr.currency,
    discount_pct: 'unavailable',
    net_price: pr.price,
    delivery_days: (typeof d.delivery === 'string' ? d.delivery.slice(0, 120) : 'unavailable'),
    warranty_months: 'unavailable',
    payment_terms: 'unavailable',
    availability: 'unavailable',
    source: 'serpapi_shopping',
    source_url: e.source_url,
    retrieved_at: e.retrieved_at,
    data_status: 'PARTIAL',
    confidence: (typeof e.confidence === 'number' ? e.confidence : 0.6),
  });
}
const seenV = new Set();
const vendors = [];
for (const o of offers) {
  if (seenV.has(o.vendor_id)) continue;
  seenV.add(o.vendor_id);
  if (!o.vendor_name || o.vendor_name === 'unavailable') throw new Error('Offer without verified merchant: ' + o.offer_id);
  vendors.push({ vendor_id: o.vendor_id, vendor_name: o.vendor_name, vendor_url: o.source_url, source: o.source, source_url: o.source_url, retrieved_at: o.retrieved_at, data_status: o.data_status, confidence: o.confidence ?? 0.6, raw: { derived_from_offer: o.offer_id } });
}
return [{ json: { procurement_id: inp.procurement_id, offers, vendors, data_status: offers.length ? 'PARTIAL' : 'UNAVAILABLE', unavailable_reasons: offers.length ? [] : ['No attributable commercial evidence'], skipped } }];
